mapper.select:
SELECT s.mcp_server_id, s.server_code, s.server_name, s.description, s.status, s.revision, s.latest_version_id, s.latest_version_no, s.latest_readiness, v.transport_type, v.endpoint, ( SELECT count(DISTINCT t.tool_id) FROM squad_chat.sq_tool t JOIN squad_chat.sq_tool_version tv ON tv.tool_version_id = t.latest_version_id WHERE t.deleted_at IS NULL AND tv.mcp_server_id = s.mcp_server_id ) AS usage_count, s.last_update_time FROM squad_chat.sq_mcp_server s LEFT JOIN squad_chat.sq_mcp_server_version v ON v.mcp_server_version_id = s.latest_version_id WHERE s.deleted_at IS NULL
AND s.mcp_server_id = #{mcpServerId}
ORDER BY s.last_update_time DESC, s.id DESC
